import {
  Cell as AriaCell,
  Column as AriaColumn,
  ColumnResizer as AriaColumnResizer,
  ResizableTableContainer as AriaResizableTableContainer,
  Row as AriaRow,
  Table as AriaTable,
  TableBody as AriaTableBody,
  TableFooter as AriaTableFooter,
  TableHeader as AriaTableHeader,
  TableLoadMoreItem as AriaTableLoadMoreItem,
} from "react-aria-components";
import type {
  CellProps as AriaCellProps,
  ColumnProps as AriaColumnProps,
  ColumnResizerProps as AriaColumnResizerProps,
  ResizableTableContainerProps as AriaResizableTableContainerProps,
  RowProps as AriaRowProps,
  TableBodyProps as AriaTableBodyProps,
  TableFooterProps as AriaTableFooterProps,
  TableHeaderProps as AriaTableHeaderProps,
  TableLoadMoreItemProps as AriaTableLoadMoreItemProps,
  TableProps as AriaTableProps,
} from "react-aria-components";
import { ChevronDown, ChevronUp } from "./icons";
import type { Ref } from "react";
import "./Table.css";

export interface TableProps extends Omit<AriaTableProps, "className"> {
  /** Optional extra class. sd-table is always preserved. */
  className?: string;
  /** Passed to the underlying table/div DOM node. */
  ref?: Ref<HTMLTableElement | HTMLDivElement>;
}

export function Table({ className, ...props }: TableProps) {
  return (
    <AriaTable
      {...props}
      className={className ? `sd-table ${className}` : "sd-table"}
    />
  );
}

export interface TableHeaderProps<T extends object = object>
  extends Omit<AriaTableHeaderProps<T>, "className"> {
  /** Optional extra class. sd-table__header is always preserved. */
  className?: string;
  /** Passed to the underlying thead/div DOM node. */
  ref?: Ref<HTMLTableSectionElement | HTMLDivElement>;
}

export function TableHeader<T extends object = object>({
  className,
  ...props
}: TableHeaderProps<T>) {
  return (
    <AriaTableHeader
      {...props}
      className={className ? `sd-table__header ${className}` : "sd-table__header"}
    />
  );
}

export interface TableColumnProps extends Omit<AriaColumnProps, "className"> {
  /**
   * Inline alignment of the header. `end` for a numeric column (an amount, a count), so its digits
   * line up on the side the column's cells share. Give the column's cells the same value.
   *
   * @default "start"
   */
  align?: "start" | "end";
  /** Optional extra class. sd-table__column is always preserved. */
  className?: string;
  /** Passed to the underlying th/div DOM node. */
  ref?: Ref<HTMLTableCellElement | HTMLDivElement>;
}

export function TableColumn({ align = "start", className, children, textValue, ...props }: TableColumnProps) {
  return (
    <AriaColumn
      {...props}
      data-align={align}
      textValue={textValue || (typeof children === "string" ? children : undefined)}
      className={
        className
          ? `sd-table__column sd-type-label-medium ${className}`
          : "sd-table__column sd-type-label-medium"
      }
    >
      {(renderProps) => (
        <>
          {typeof children === "function" ? children(renderProps) : children}
          {/* Sortable columns get a direction arrow so ascending vs descending is
              distinguishable — react-aria only exposes it via aria-sort otherwise. */}
          {renderProps.sortDirection && (
            <span aria-hidden="true" className="sd-table__sort-indicator">
              {renderProps.sortDirection === "ascending" ? (
                <ChevronUp size="1em" />
              ) : (
                <ChevronDown size="1em" />
              )}
            </span>
          )}
        </>
      )}
    </AriaColumn>
  );
}

export interface TableBodyProps<T extends object = object>
  extends Omit<AriaTableBodyProps<T>, "className"> {
  /** Optional extra class. sd-table__body is always preserved. */
  className?: string;
  /** Passed to the underlying tbody/div DOM node. */
  ref?: Ref<HTMLTableSectionElement | HTMLDivElement>;
}

export function TableBody<T extends object = object>({
  className,
  ...props
}: TableBodyProps<T>) {
  return (
    <AriaTableBody
      {...props}
      className={className ? `sd-table__body ${className}` : "sd-table__body"}
    />
  );
}

export interface TableFooterProps<T extends object = object>
  extends Omit<AriaTableFooterProps<T>, "className"> {
  /** Optional extra class. sd-table__footer is always preserved. */
  className?: string;
  /** Passed to the underlying tfoot/div DOM node. */
  ref?: Ref<HTMLTableSectionElement | HTMLDivElement>;
}

export function TableFooter<T extends object = object>({
  className,
  ...props
