}

export interface TableRowProps<T extends object = object>
  extends Omit<AriaRowProps<T>, "className"> {
  /** Optional extra class. sd-table__row is always preserved. */
  className?: string;
  /** Passed to the underlying tr/div DOM node. */
  ref?: Ref<HTMLTableRowElement | HTMLDivElement>;
}

export function TableRow<T extends object = object>({ className, ...props }: TableRowProps<T>) {
  return (
    <AriaRow
      {...props}
      className={className ? `sd-table__row ${className}` : "sd-table__row"}
    />
  );
}

export interface TableCellProps extends Omit<AriaCellProps, "className"> {
  /**
   * Inline alignment of the cell, matching its column's `align`.
   *
   * @default "start"
   */
  align?: "start" | "end";
  /** Optional extra class. sd-table__cell is always preserved. */
  className?: string;
  /** Passed to the underlying td/div DOM node. */
  ref?: Ref<HTMLTableCellElement | HTMLDivElement>;
}

export function TableCell({ align = "start", className, ...props }: TableCellProps) {
  return (
    <AriaCell
      {...props}
      data-align={align}
      className={
        className
          ? `sd-table__cell sd-type-body-medium ${className}`
          : "sd-table__cell sd-type-body-medium"
      }
    />
  );
}

export interface TableLoadMoreItemProps
  extends Omit<AriaTableLoadMoreItemProps, "className" | "children"> {
  /** Loading-row content — required; the .tsx bakes no default text (contract §7b: no
   *  default content, and a hardcoded "Loading…" would ship untranslated English).
   *  Supply e.g. a Spinner or a localized cell. */
  children: AriaTableLoadMoreItemProps["children"];
  /** Optional extra class. sd-table__load-more is always preserved. */
  className?: string;
  /** Passed to the underlying tr DOM node. */
  ref?: Ref<HTMLTableRowElement>;
}

export function TableLoadMoreItem({
  children,
  className,
  isLoading = true,
  ...props
}: TableLoadMoreItemProps) {
  return (
    <AriaTableLoadMoreItem
      {...props}
      isLoading={isLoading}
      className={
        className
          ? `sd-table__load-more sd-type-caption-medium ${className}`
          : "sd-table__load-more sd-type-caption-medium"
      }
    >
      {/* React Aria generates the row's single `colSpan` cell itself and exposes no hook to
          class it, and a `<tr>` cannot take padding — so `.sd-table__load-more-cell` had no
          element to land on and its padding never applied. The children we render DO sit inside
          that cell, so this wrapper is the one reachable box: it restores the padded, centred
          load-more content the other collections get directly on their own load-more element. */}
      <div className="sd-table__load-more-cell">{children}</div>
    </AriaTableLoadMoreItem>
  );
}

export interface ResizableTableContainerProps
  extends Omit<AriaResizableTableContainerProps, "className"> {
  /** Additional class (optional). sd-table__container is always preserved. */
  className?: string;
  /** Forwarded to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ResizableTableContainer({
  className,
  ref,
  ...props
}: ResizableTableContainerProps) {
  return (
    <AriaResizableTableContainer
      {...props}
      ref={ref}
      className={className ? `sd-table__container ${className}` : "sd-table__container"}
    />
  );
}

export interface ColumnResizerProps extends Omit<AriaColumnResizerProps, "className"> {
  /** Additional class (optional). sd-table__resizer is always preserved. */
  className?: string;
  /** Forwarded to the underlying <div> DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColumnResizer({ className, ...props }: ColumnResizerProps) {
  return (
    <AriaColumnResizer
      {...props}
      className={className ? `sd-table__resizer ${className}` : "sd-table__resizer"}
    />
  );
}

.sd-table {
  --sd-table-body-background-current: var(--sd-table-body-background);
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  background: var(--sd-table-background);
  color: var(--sd-table-foreground);
  border: var(--sd-table-border-width) solid var(--sd-table-border);
  border-radius: var(--sd-table-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-table__header {
  background: var(--sd-table-header-background);
  color: var(--sd-table-header-foreground);
}

.sd-table__column {
  position: relative;
  isolation: isolate;
  padding: var(--sd-table-column-padding-block) var(--sd-table-column-padding-inline);
  border-block-end: var(--sd-table-column-border-width) solid var(--sd-table-column-border);
  color: var(--sd-table-column-foreground);
  text-align: start;
  outline: none;
}

.sd-table__column[data-allows-sorting] {
  cursor: pointer;
}

.sd-table__column::after {
  content: "";
  position: absolute;
  inset: 0;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-table__column[data-hovered]::after {
  background: var(--sd-state-hover);
}

.sd-table__column[data-pressed]::after {
  background: var(--sd-state-pressed);
}

.sd-table__column[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-table__column[data-sort-direction="ascending"],
.sd-table__column[data-sort-direction="descending"] {
  color: var(--sd-table-column-foreground-sorted);
}
/* Raised to `text.DEFAULT` while hovered or pressed: the resting ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). A sorted header keeps its arrow. Declared after the sorted rule, so it wins at equal specificity. */
.sd-table__column[data-hovered],
.sd-table__column[data-pressed] {
  color: var(--sd-table-column-foreground-hover);
}

/* sort direction arrow — inherits the sorted color via currentColor, sits after the label. */
.sd-table__sort-indicator {
  /* A flex box, so the glyph centres on the header line instead of sitting on its baseline. */
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  margin-inline-start: var(--sd-table-sort-indicator-gap);
  font-size: var(--sd-table-sort-indicator-font-size);
}

.sd-table__body {
  background: var(--sd-table-body-background-current);
}

.sd-table__footer {
  background: var(--sd-table-footer-background);
  color: var(--sd-table-footer-foreground);
}

.sd-table__row {
  position: relative;
  isolation: isolate;
  color: var(--sd-table-row-foreground);
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-table-row-state-hover-current: var(--sd-state-hover);
  --sd-table-row-state-pressed-current: var(--sd-state-pressed);
}
/* Interaction state-layer overlay over the row (composites with selected) (ADR-0009). */
.sd-table__row::after {
  content: "";
  position: absolute;
  inset: 0;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-table__row[data-hovered]::after {
  background: var(--sd-table-row-state-hover-current);
}

.sd-table__row[data-pressed]::after {
  background: var(--sd-table-row-state-pressed-current);
}

.sd-table__row[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-table__row[data-selected] {
  background: var(--sd-table-row-background-selected);
  --sd-table-row-state-hover-current: var(--sd-state-hover-selected);
  --sd-table-row-state-pressed-current: var(--sd-state-pressed-selected);
}

.sd-table__row[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-table__row[data-dragging] {
  opacity: var(--sd-state-dragging);
}

.sd-table__row[data-drop-target] {
  background: var(--sd-table-row-background-drop-target);
}

/* Dropping onto the table root (not just onto/between rows) also gets the drop-target
   highlight. RAC emits this state on the root; TableBody emits only data-empty. */
.sd-table[data-drop-target] {
  --sd-table-body-background-current: var(--sd-table-background-drop-target);
  background: var(--sd-table-background-drop-target);
}

.sd-table__cell {
  padding: var(--sd-table-cell-padding-block) var(--sd-table-cell-padding-inline);
  border-block-end: var(--sd-table-cell-border-width) solid var(--sd-table-cell-border);
  color: var(--sd-table-cell-foreground);
  vertical-align: middle;
  /* Digits line up down a column only at one width each. */
  font-variant-numeric: tabular-nums;
  outline: none;
}

/* A numeric column sits on the end side, header and cells alike, so its digits align by place. */
.sd-table__column[data-align="end"],
.sd-table__cell[data-align="end"] {
  text-align: end;
}

.sd-table__cell[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-table__load-more {
  color: var(--sd-table-load-more-foreground);
}

.sd-table__load-more-cell {
  padding: var(--sd-table-load-more-padding-block) var(--sd-table-load-more-padding-inline);
  color: var(--sd-table-load-more-foreground);
  text-align: center;
}

.sd-table__container {
  overflow: auto;
  max-width: 100%;
  border-radius: var(--sd-table-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-table__resizer {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  width: var(--sd-table-resizer-width);
  cursor: col-resize;
  touch-action: none;
}

.sd-table__resizer::after {
  content: "";
  position: absolute;
  inset-block: var(--sd-table-resizer-inset-block);
  inset-inline-start: 50%;
  width: var(--sd-table-resizer-line-width);
  background: var(--sd-table-resizer-background);
  translate: -50%;
}

.sd-table__resizer[data-hovered]::after,
.sd-table__resizer[data-resizing]::after {
  background: var(--sd-table-resizer-background-active);
}

.sd-table__resizer[data-focus-visible]::after {
  width: var(--sd-table-resizer-line-width-focus);
  background: color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
}
